package org.apache.commons.lang;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.lang.math.NumberUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for org.apache.commons.lang.BooleanUtils.isFalse(Boolean bool)
 */
public class BooleanUtils_isFalse_TriageGen0Test {

    @Test
    public void testIsFalse_withNull() {
        // Branch: if (bool == null) -> returns false
        Boolean input = null;
        boolean result = BooleanUtils.isFalse(input);
        assertFalse("isFalse(null) should return false", result);
    }

    @Test
    public void testIsFalse_withTrue() {
        // Branch: bool.booleanValue() is true -> returns false
        Boolean input = Boolean.TRUE;
        boolean result = BooleanUtils.isFalse(input);
        assertFalse("isFalse(true) should return false", result);
    }

    @Test
    public void testIsFalse_withFalse() {
        // Branch: bool.booleanValue() is false -> returns true
        Boolean input = Boolean.FALSE;
        boolean result = BooleanUtils.isFalse(input);
        assertTrue("isFalse(false) should return true", result);
    }
}
